package in.tallybridge.app;

import android.app.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.math.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.ExecutorService;

/** In-memory composer only. No preferences, database or Tally writes. */
final class ProformaComposer {
 interface Review {void show(JSONObject result,String payload);}
 final Activity activity;final BridgeApi api;final ExecutorService work;final String company;final Review review;
 final JSONObject draft=new JSONObject();final JSONArray lines=new JSONArray();
 JSONObject masters;boolean busy=false;LinearLayout panel,itemsPanel;TextView summary,status;final Map<String,EditText> fields=new HashMap<>();final Map<String,Spinner> states=new HashMap<>();
 final int ink,muted,surface,bg,accent;final boolean dark;
 static final String[] STATES={"01 Jammu and Kashmir","02 Himachal Pradesh","03 Punjab","04 Chandigarh","05 Uttarakhand","06 Haryana","07 Delhi","08 Rajasthan","09 Uttar Pradesh","10 Bihar","11 Sikkim","12 Arunachal Pradesh","13 Nagaland","14 Manipur","15 Mizoram","16 Tripura","17 Meghalaya","18 Assam","19 West Bengal","20 Jharkhand","21 Odisha","22 Chhattisgarh","23 Madhya Pradesh","24 Gujarat","26 Dadra and Nagar Haveli and Daman and Diu","27 Maharashtra","28 Andhra Pradesh (old code)","29 Karnataka","30 Goa","31 Lakshadweep","32 Kerala","33 Tamil Nadu","34 Puducherry","35 Andaman and Nicobar Islands","36 Telangana","37 Andhra Pradesh","38 Ladakh"};
 ProformaComposer(Activity a,BridgeApi api,ExecutorService work,String company,boolean dark,Review review){this.activity=a;this.api=api;this.work=work;this.company=company;this.dark=dark;this.review=review;ink=dark?0xffe4ebf2:0xff142d45;muted=dark?0xffa6b7c4:0xff596d7f;surface=dark?0xff1c2a35:Color.WHITE;bg=dark?0xff0f181f:0xfff2f5f9;accent=dark?0xff7dd7c0:0xff087f72;put(draft,"company",company);put(draft,"number","PI-"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss"))+"-"+UUID.randomUUID().toString().substring(0,4).toUpperCase(Locale.ROOT));put(draft,"date",LocalDate.now().toString());put(draft,"supplierState","27");put(draft,"placeState","27");}
 int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 static void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(JSONException e){throw new IllegalArgumentException(e);}}
 TextView text(String s,int size,int color){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
 GradientDrawable shape(){GradientDrawable d=new GradientDrawable();d.setColor(surface);d.setCornerRadius(dp(12));d.setStroke(dp(1),dark?0xff344a59:0xffd7e1e9);return d;}
 LinearLayout column(){LinearLayout c=new LinearLayout(activity);c.setOrientation(LinearLayout.VERTICAL);return c;}
 Button button(String label,Runnable action){Button b=new Button(activity);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setMinHeight(dp(48));b.setPadding(dp(14),dp(10),dp(14),dp(10));b.setStateListAnimator(null);b.setBackgroundTintList(null);GradientDrawable background=shape();boolean primary=label.equals("Review proforma")||label.startsWith("+ Add");if(primary)background.setColor(accent);b.setBackground(background);b.setTextColor(primary?(dark?0xff0b3028:Color.WHITE):ink);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(6);lp.bottomMargin=dp(6);b.setLayoutParams(lp);b.setOnClickListener(v->action.run());return b;}
 void title(LinearLayout parent,String s){TextView t=text(s,19,ink);t.setTypeface(null,Typeface.BOLD);t.setPadding(0,dp(20),0,dp(8));parent.addView(t);}
 EditText input(LinearLayout parent,JSONObject object,String key,String label,boolean number,boolean multi){parent.addView(text(label,12,muted));EditText e=new EditText(activity);e.setTextColor(ink);e.setHintTextColor(muted);e.setTextSize(15);e.setBackground(shape());e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setText(object.optString(key));e.setSingleLine(!multi);if(multi){e.setMinLines(2);e.setMaxLines(5);e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);}else if(number)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(multi?2000:160)});e.setContentDescription(label);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);parent.addView(e,lp);e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){put(object,key,s.toString().trim());if(object==draft){if(key.equals("buyerGST")&&s.length()>=2)setState("placeState",s.subSequence(0,2).toString());if(key.equals("supplierGST")&&s.length()>=2)setState("supplierState",s.subSequence(0,2).toString());refreshTotal();}}public void afterTextChanged(Editable e){}});if(object==draft)fields.put(key,e);return e;}
 void setField(String k,String v){put(draft,k,v);EditText e=fields.get(k);if(e!=null)e.setText(v);}
 void stateBox(String key,String label){panel.addView(text(label,12,muted));Spinner s=new Spinner(activity);ArrayAdapter<String> adapter=new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,STATES);s.setAdapter(adapter);states.put(key,s);setState(key,draft.optString(key,"27"));panel.addView(s,new LinearLayout.LayoutParams(-1,dp(52)));s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){put(draft,key,STATES[pos].substring(0,2));if(v instanceof TextView)((TextView)v).setTextColor(ink);refreshTotal();}public void onNothingSelected(AdapterView<?> p){}});}
 void setState(String key,String code){for(int i=0;i<STATES.length;i++)if(STATES[i].startsWith(code+" ")){put(draft,key,code);Spinner s=states.get(key);if(s!=null)s.setSelection(i);return;}}
 void setStateName(String key,String name){if(name==null||name.trim().isEmpty())return;String wanted=name.trim();for(int i=0;i<STATES.length;i++){String label=STATES[i].substring(3).trim();if(label.equalsIgnoreCase(wanted)){setState(key,STATES[i].substring(0,2));return;}}}
 void render(LinearLayout body){fields.clear();states.clear();ScrollView scroll=new ScrollView(activity);panel=column();panel.setPadding(dp(20),dp(8),dp(20),dp(24));scroll.addView(panel);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));panel.addView(text("A temporary quotation — never posted to Tally",14,muted));status=text("Loading Tally parties and stock items…",13,accent);panel.addView(status);panel.addView(button("Refresh Tally masters",()->loadMasters(true)));
 title(panel,"Proforma details");input(panel,draft,"number","Proforma number",false,false);input(panel,draft,"date","Date • YYYY-MM-DD",false,false);
 title(panel,"Your business");panel.addView(text(company,17,ink));input(panel,draft,"supplierGST","Supplier GSTIN (if registered)",false,false);input(panel,draft,"supplierAddress","Supplier address",false,true);stateBox("supplierState","Supplier state");
 title(panel,"Buyer");panel.addView(button("Choose a Tally party",this::chooseParty));panel.addView(text("Or enter a temporary buyer below. No ledger will be created.",13,muted));input(panel,draft,"buyer","Buyer / company name",false,false);input(panel,draft,"buyerGST","Buyer GSTIN (leave blank if unregistered)",false,false);input(panel,draft,"city","City",false,false);input(panel,draft,"address","Buyer address",false,true);stateBox("placeState","Place of supply / delivery state");panel.addView(text("Defaults from buyer GSTIN. Confirm the delivery state, especially for unregistered buyers.",12,muted));
 title(panel,"Stock items");itemsPanel=column();panel.addView(itemsPanel);panel.addView(button("+ Add Tally stock item",this::chooseItem));refreshItems();
 title(panel,"Dispatch & notes");input(panel,draft,"dispatch","Dispatched through",false,false);input(panel,draft,"lr","LR / RR number (optional)",false,false);input(panel,draft,"notes","Notes / payment terms",false,true);
 summary=text("Add items to calculate totals",16,ink);summary.setBackground(shape());summary.setPadding(dp(14),dp(14),dp(14),dp(14));panel.addView(summary);refreshTotal();panel.addView(button("Review proforma",this::submit));panel.addView(text("Draft is held only in memory. Shared PDFs/messages remain in the receiving app.",12,muted));if(masters==null)loadMasters(false);else showMasterStatus();}
 void showMasterStatus(){if(status==null||masters==null)return;JSONObject stock=masters.optJSONObject("stock");status.setText((stock!=null&&stock.optBoolean("stale")?"Saved Tally masters — ":"Tally masters loaded — ")+"confirm prices and GST rates before sharing.");}
 void loadMasters(boolean refresh){if(busy)return;busy=true;final LinearLayout target=panel;status.setText("Reading Tally masters…");work.execute(()->{try{JSONObject result=api.get(BridgeApi.path("proforma-masters",company)+(refresh?"&refresh=1":""));activity.runOnUiThread(()->{busy=false;masters=result;if(target!=panel||!target.isAttachedToWindow())return;JSONObject supplier=result.optJSONObject("supplier");if(supplier!=null){if(draft.optString("supplierGST").isEmpty())setField("supplierGST",supplier.optString("gstin"));if(draft.optString("supplierAddress").isEmpty()){String a=supplier.optString("address"),pin=supplier.optString("pincode");if(!pin.isEmpty()&&!a.contains(pin))a+=(a.isEmpty()?"":", ")+pin;setField("supplierAddress",a);}String code=supplier.optString("stateCode");if(!code.isEmpty())setState("supplierState",code);else setStateName("supplierState",supplier.optString("state"));}showMasterStatus();});}catch(Exception e){activity.runOnUiThread(()->{busy=false;if(target==panel&&target.isAttachedToWindow())status.setText("Could not load masters: "+e.getMessage()+". Tap Refresh Tally masters.");});}});}
 interface Pick{void item(JSONObject item);}
 void choose(JSONArray source,String title,Pick action){if(source==null||source.length()==0){Toast.makeText(activity,"No entries loaded. Refresh Tally masters.",Toast.LENGTH_LONG).show();return;}LinearLayout box=column();box.setPadding(dp(16),dp(8),dp(16),dp(8));EditText search=new EditText(activity);search.setHint("Search by name");search.setSingleLine(true);box.addView(search);ListView list=new ListView(activity);box.addView(list,new LinearLayout.LayoutParams(-1,dp(300)));ArrayList<String> names=new ArrayList<>();Map<String,JSONObject> index=new HashMap<>();for(int i=0;i<source.length();i++){JSONObject o=source.optJSONObject(i);if(o!=null){names.add(o.optString("name"));index.put(o.optString("name"),o);}}ArrayAdapter<String> adapter=new ArrayAdapter<>(activity,android.R.layout.simple_list_item_1,names);list.setAdapter(adapter);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(title).setView(box).setNegativeButton("Cancel",null).create();list.setOnItemClickListener((p,v,pos,id)->{JSONObject o=index.get(adapter.getItem(pos));dialog.dismiss();action.item(o);});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){adapter.getFilter().filter(s);}public void afterTextChanged(Editable e){}});dialog.show();}
 void chooseParty(){if(masters==null){loadMasters(false);return;}choose(masters.optJSONArray("parties"),"Choose buyer",o->{if(busy)return;busy=true;String name=o.optString("name");final LinearLayout target=panel;status.setText("Reading buyer details…");work.execute(()->{try{JSONObject details=api.get(BridgeApi.path("ledger-details",company,"ledger",name)).getJSONObject("details");activity.runOnUiThread(()->{busy=false;if(target!=panel||!target.isAttachedToWindow())return;String gst=details.optString("PARTYGSTIN",details.optString("GSTIN"));String address=details.optString("ADDRESS");String pin=details.optString("PINCODE");String city=details.optString("CITY");String state=details.optString("STATENAME",details.optString("LEDSTATENAME"));setField("buyer",details.optString("MAILINGNAME",name));setField("buyerGST",gst);if(!pin.isEmpty()&&!address.contains(pin))address+=(address.isEmpty()?"":", ")+pin;setField("address",address);setField("city",city);if(gst.length()>=2)setState("placeState",gst.substring(0,2));else setStateName("placeState",state);if(gst.isEmpty()&&address.isEmpty()&&city.isEmpty())status.setText("Buyer ledger opened, but Tally returned no GST/address fields for this party.");else status.setText("Buyer details loaded from Tally.");});}catch(Exception e){activity.runOnUiThread(()->{busy=false;if(target==panel&&target.isAttachedToWindow()){setField("buyer",name);setField("buyerGST","");setField("address","");setField("city","");status.setText("Buyer details unavailable: "+e.getMessage());}});}});});}
 void chooseItem(){if(masters==null){loadMasters(false);return;}JSONObject stock=masters.optJSONObject("stock");choose(stock==null?null:stock.optJSONArray("items"),"Choose stock item",o->{JSONObject line=new JSONObject();for(String key:new String[]{"name","description","hsn","unit","gst"})put(line,key,o.optString(key));put(line,"quantity","1");put(line,"discount","0");editLine(line,-1);});}
 void editLine(JSONObject original,int position){JSONObject line;try{line=new JSONObject(original.toString());}catch(Exception e){return;}ScrollView scroll=new ScrollView(activity);LinearLayout box=column();box.setPadding(dp(18),dp(8),dp(18),dp(12));scroll.addView(box);box.addView(text(line.optString("name"),18,ink));input(box,line,"description","Additional item description",false,true);input(box,line,"quantity","Quantity",true,false);input(box,line,"unit","Unit",false,false);input(box,line,"rate","Unit price before GST (INR)",true,false);input(box,line,"discount","Discount %",true,false);input(box,line,"gst","GST % — confirm rate; 0 for exempt",true,false);input(box,line,"hsn","HSN / SAC",false,false);AlertDialog d=new AlertDialog.Builder(activity).setTitle(position<0?"Add item":"Edit item").setView(scroll).setPositiveButton(position<0?"Add":"Update",null).setNegativeButton("Cancel",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{BigDecimal q=new BigDecimal(line.optString("quantity")),r=new BigDecimal(line.optString("rate")),disc=new BigDecimal(line.optString("discount")),gst=new BigDecimal(line.optString("gst"));if(q.signum()<=0||r.signum()<0||disc.signum()<0||disc.compareTo(new BigDecimal("100"))>0||gst.signum()<0||gst.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException();if(position<0){if(lines.length()>=100)throw new IllegalArgumentException();lines.put(line);}else lines.put(position,line);d.dismiss();refreshItems();refreshTotal();}catch(Exception e){Toast.makeText(activity,"Check quantity, unit price, discount and GST percentage.",Toast.LENGTH_LONG).show();}}));d.show();}
 void refreshItems(){if(itemsPanel==null)return;itemsPanel.removeAllViews();for(int i=0;i<lines.length();i++){final int index=i;JSONObject r=lines.optJSONObject(i);LinearLayout card=column();card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setBackground(shape());card.addView(text((i+1)+". "+r.optString("name"),16,ink));card.addView(text(r.optString("quantity")+" "+r.optString("unit")+" × ₹"+r.optString("rate")+"\nDiscount "+r.optString("discount")+"% • GST "+r.optString("gst")+"%",13,muted));if(!r.optString("description").isEmpty())card.addView(text(r.optString("description"),13,muted));LinearLayout actions=new LinearLayout(activity);actions.addView(button("Edit",()->editLine(r,index)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("Remove",()->{lines.remove(index);refreshItems();refreshTotal();}),new LinearLayout.LayoutParams(0,-2,1));card.addView(actions);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);itemsPanel.addView(card,lp);}}
 void refreshTotal(){if(summary==null)return;try{BigDecimal net=BigDecimal.ZERO,discount=BigDecimal.ZERO,tax=BigDecimal.ZERO;boolean local=draft.optString("supplierState").equals(draft.optString("placeState"));for(int i=0;i<lines.length();i++){JSONObject r=lines.getJSONObject(i);BigDecimal gross=new BigDecimal(r.getString("quantity")).multiply(new BigDecimal(r.getString("rate"))).setScale(2,RoundingMode.HALF_UP);BigDecimal d=gross.multiply(new BigDecimal(r.getString("discount"))).divide(new BigDecimal("100")).setScale(2,RoundingMode.HALF_UP);BigDecimal n=gross.subtract(d);BigDecimal t=n.multiply(new BigDecimal(r.getString("gst"))).divide(new BigDecimal(local?"200":"100")).setScale(2,RoundingMode.HALF_UP);if(local)t=t.multiply(new BigDecimal("2"));net=net.add(n);discount=discount.add(d);tax=tax.add(t);}BigDecimal before=net.add(tax).setScale(2,RoundingMode.HALF_UP);BigDecimal total=before.setScale(0,RoundingMode.HALF_UP).setScale(2);BigDecimal round=total.subtract(before).setScale(2);summary.setText("Discount  ₹"+discount.setScale(2)+"\nTaxable  ₹"+net.setScale(2)+"\n"+(local?"CGST + SGST":"IGST")+"  ₹"+tax.setScale(2)+"\nRound off  ₹"+round+"\nTotal  ₹"+total);}catch(Exception e){summary.setText("Complete quantity, rate and GST for every item.");}}
 void submit(){if(busy)return;if(lines.length()==0){Toast.makeText(activity,"Add at least one Tally stock item",Toast.LENGTH_LONG).show();return;}put(draft,"items",lines);final String payload=draft.toString();final LinearLayout target=panel;busy=true;status.setText("Checking proforma totals…");work.execute(()->{try{JSONObject result=api.call("/api/v1/mobile/proforma-preview","POST",payload);activity.runOnUiThread(()->{busy=false;if(target==panel&&target.isAttachedToWindow())review.show(result,payload);});}catch(Exception e){activity.runOnUiThread(()->{busy=false;if(target==panel&&target.isAttachedToWindow())new AlertDialog.Builder(activity).setTitle("Check proforma").setMessage(e.getMessage()).setPositiveButton("OK",null).show();});}});}
}
